<main>
  <h1>Kvíz a Dunáról</h1>
  <p class="hint">Válaszolj 10 kérdésre a Duna folyóról. Válassz egyet a négy válasz közül, majd lépj a következőre. A végén megmutatjuk a pontszámot.</p>

  <section id="quiz" class="card">
    <p class="progress" id="progress"></p>
    <h2 class="qtext" id="qtext"></h2>
    <div class="options" id="options" role="group" aria-label="Válaszlehetőségek"></div>
    <p class="feedback" id="feedback" role="status" aria-live="polite"></p>
    <div class="actions"><button class="btn hidden" id="next">Következő kérdés</button></div>
  </section>

  <section id="results" class="card hidden">
    <h2>Eredmény</h2>
    <div class="bar" aria-hidden="true"><div class="bar-fill" id="barFill"></div></div>
    <p class="score" id="score"></p>
    <p class="verdict" id="verdict"></p>
    <ul class="review" id="review"></ul>
    <div class="row">
      <button class="btn" id="restart">Újrakezdés</button>
      <button class="btn secondary hidden" id="forget">Mentett eredmény törlése</button>
    </div>
  </section>
</main>

<script>
const QUESTIONS = [
  { q: "Hány országon halad át a Duna?", a: ["9", "10", "11", "12"], c: 1 },
  { q: "Melyik hegyvidéken ered a Duna?", a: ["Alpok", "Fekete-erdő", "Tátra", "Kárpátok"], c: 1 },
  { q: "Hány fővárost érint a Duna?", a: ["2", "3", "4", "5"], c: 2 },
  { q: "Hány kilométer hosszú a Duna?", a: ["2100 km", "2500 km", "2850 km", "3100 km"], c: 2 },
  { q: "Melyik tengerbe ömlik a Duna?", a: ["Adria", "Északi-tenger", "Fekete-tenger", "Balti-tenger"], c: 2 },
  { q: "Melyik a Duna leghosszabb mellékfolyója?", a: ["Dráva", "Tisza", "Sáva", "Morva"], c: 2 },
  { q: "Melyik két fővárost választja el egymástól a Duna?", a: ["Bécs és Pozsony", "Budapest és Esztergom", "Bécs és Budapest", "Belgrád és Esztergom"], c: 0 },
  { q: "Hány nemzeti park van a Duna mentén?", a: ["1", "4", "10", "15"], c: 2 },
  { q: "Melyik a Duna leghíresebb szurdoka?", a: ["Temes-kanyon", "Vaskapu", "Frigyes-kanyon", "Bécsi-kanyon"], c: 1 },
  { q: "Melyik magyar fővároson halad át a Duna?", a: ["Szeged", "Pécs", "Győr", "Budapest"], c: 3 }
];

const LETTERS = ["A", "B", "C", "D"];
const KEY = "duna-quiz";

const el = id => document.getElementById(id);
const quiz = el("quiz"), results = el("results");
const progress = el("progress"), qtext = el("qtext"), options = el("options");
const feedback = el("feedback"), nextBtn = el("next");
const score = el("score"), verdict = el("verdict"), review = el("review");
const barFill = el("barFill"), restart = el("restart"), forget = el("forget");

let idx = 0, answers = [], answered = false;

function save() {
  if (window.alfy && window.alfy.storage) {
    window.alfy.storage.set(KEY, { answers, idx }).catch(() => {});
  }
}

function renderQuestion() {
  const item = QUESTIONS[idx];
  answered = false;
  progress.textContent = (idx + 1) + ". / " + QUESTIONS.length + " kérdés";
  qtext.textContent = item.q;
  feedback.textContent = "";
  feedback.className = "feedback";
  nextBtn.classList.add("hidden");
  options.innerHTML = "";
  item.a.forEach((text, i) => {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "opt";
    b.innerHTML = '<span class="letter">' + LETTERS[i] + '</span><span></span>';
    b.lastChild.textContent = text;
    b.addEventListener("click", () => choose(i, b));
    options.appendChild(b);
  });
  quiz.classList.remove("hidden");
  results.classList.add("hidden");
}

function choose(i, btn) {
  if (answered) return;
  answered = true;
  answers[idx] = i;
  const correct = QUESTIONS[idx].c;
  [...options.children].forEach((child, j) => {
    child.disabled = true;
    if (j === correct) child.classList.add("correct");
  });
  if (i === correct) {
    feedback.textContent = "Helyes!";
    feedback.className = "feedback ok";
  } else {
    btn.classList.add("wrong");
    feedback.textContent = "Sajnos nem. A helyes válasz: " + LETTERS[correct] + " – " + QUESTIONS[idx].a[correct];
    feedback.className = "feedback no";
  }
  nextBtn.textContent = idx === QUESTIONS.length - 1 ? "Eredmény megjelenítése" : "Következő kérdés";
  nextBtn.classList.remove("hidden");
  nextBtn.focus();
  save();
}

function finish() {
  const correct = answers.filter((a, i) => a === QUESTIONS[i].c).length;
  quiz.classList.add("hidden");
  results.classList.remove("hidden");
  score.innerHTML = correct + " <small>/ " + QUESTIONS.length + " pont</small>";
  barFill.style.width = (correct / QUESTIONS.length * 100) + "%";
  verdict.textContent = verdictFor(correct);
  review.innerHTML = "";
  QUESTIONS.forEach((item, i) => {
    const ok = answers[i] === item.c;
    const li = document.createElement("li");
    const mark = document.createElement("span");
    mark.className = "mark " + (ok ? "ok" : "no");
    mark.textContent = ok ? "✓" : "✗";
    const rq = document.createElement("div");
    rq.className = "rq";
    rq.textContent = (i + 1) + ". " + item.q;
    const ra = document.createElement("div");
    ra.className = "ra";
    ra.appendChild(mark.cloneNode(true));
    ra.appendChild(document.createTextNode("Helyes válasz: "));
    const b = document.createElement("b");
    b.textContent = item.a[item.c];
    ra.appendChild(b);
    li.appendChild(rq);
    li.appendChild(ra);
    review.appendChild(li);
  });
  forget.classList.toggle("hidden", !(window.alfy && window.alfy.storage));
  restart.focus();
}

function verdictFor(c) {
  if (c === 10) return "Tökéletes! A Duna szakértője vagy.";
  if (c >= 8) return "Kiváló eredmény!";
  if (c >= 6) return "Jó eredmény, de még van mit tanulni.";
  if (c >= 4) return "Nem rossz, de érdemes utánanézni.";
  return "Sajnos kevés pont – próbáld újra!";
}

nextBtn.addEventListener("click", () => {
  if (idx === QUESTIONS.length - 1) {
    save();
    finish();
  } else {
    idx++;
    save();
    renderQuestion();
  }
});

restart.addEventListener("click", () => {
  idx = 0;
  answers = [];
  save();
  renderQuestion();
});

forget.addEventListener("click", async () => {
  if (window.alfy && window.alfy.storage) {
    try { await window.alfy.storage.set(KEY, null); } catch (e) {}
  }
  forget.classList.add("hidden");
});

async function init() {
  let state = null;
  if (window.alfy && window.alfy.storage) {
    try { state = await window.alfy.storage.get(KEY); } catch (e) {}
  }
  if (state && Array.isArray(state.answers) && state.answers.length) {
    answers = state.answers;
    if (answers.length >= QUESTIONS.length) {
      idx = QUESTIONS.length - 1;
      finish();
    } else {
      idx = Math.min(state.idx || answers.length, QUESTIONS.length - 1);
      renderQuestion();
    }
  } else {
    renderQuestion();
  }
}
init();
</script>
</body>
